-- Bump venue coverage per city from 1 to 5, so the Venues catalog has real
-- choice within a city instead of a single placeholder result. Adds 4 more
-- venues (cycling through the venue types not already used) for each of
-- the 255 cities seeded in migration 0007, with coordinates copied from
-- the same city center used in 0008 and then jittered like every other
-- venue row (see 0009).
--
-- The temporary _seed_marker column exists only so the jitter step below
-- can find exactly the rows this migration just inserted, without having
-- to repeat all 1,020 names in a second WHERE clause. A data-modifying
-- WITH (insert ... returning, then update) can't do this in one statement
-- -- Postgres runs every part of a WITH against the same snapshot, so a
-- later part can't see rows an earlier part just inserted.
-- Run this once -- re-running will jitter these rows further.
alter table venues add column if not exists _seed_marker boolean;

insert into venues (name, region, state, city, venue_type, capacity, price_tier, description, latitude, longitude, _seed_marker)
